    private static void Check(bool ok,string message){if(!ok)throw new Exception("FAIL: "+message);passed++;Console.WriteLine("PASS: "+message);}
    private static void Throws<T>(Action action,string name) where T:Exception {try{action();}catch(T){Check(true,name);return;}throw new Exception("FAIL expected "+typeof(T).Name+": "+name);}
    private static async Task ThrowsAsync<T>(Func<Task> action,string name) where T:Exception {try{await action();}catch(T){Check(true,name);return;}throw new Exception("FAIL expected "+typeof(T).Name+": "+name);}
    private static MarketEvent Trade(int second,decimal price=2,decimal size=10,decimal? cumulative=null)=>new(Us,EventKind.Trade,Epoch.AddSeconds(second),Epoch.AddSeconds(second),"TEST",second){TradePrice=price,LastPrice=price,TradeSize=size,CumulativeVolume=cumulative,PreviousClose=2};
    private static MarketEvent Quote(int second,decimal bid=1.99m,decimal ask=2.01m,decimal size=100)=>new(Us,EventKind.Quote,Epoch.AddSeconds(second),Epoch.AddSeconds(second),"TEST",second){Bid=bid,Ask=ask,BidSize=size,AskSize=size};
    private static TradingSettings Settings(){var s=new TradingSettings();s.Scalping.Enabled=s.Box.Enabled=s.Rebound.Enabled=false;s.Execution.SlippagePercent=0;s.Execution.FeePercent=.1m;s.Execution.ParticipationPercent=50;s.Execution.LatencyMs=0;return s;}
    private static void CoreTests()
    {
        var s=new TradingSettings();s.Validate();Check(true,"typed defaults validate");s.Scalping.RelativeVolume=-1;Throws<InvalidOperationException>(s.Validate,"negative strategy threshold blocked");s=new();s.Scalping.CurrentSeconds=s.Scalping.AverageSeconds;Throws<InvalidOperationException>(s.Validate,"overlapping volume baseline invalid");s=new();s.Data.Universe="NASDAQ:AAPL,NASDAQ:AAPL";Throws<InvalidOperationException>(s.Validate,"duplicate universe rejected");s=new();s.Backtest.To=s.Backtest.From;Throws<InvalidOperationException>(s.Validate,"empty backtest range rejected");
        var db=Path.Combine(Dir,"state.db");using(var store=new TradingStore(db)){s=new();store.Save("기본",s);s.Scalping.RelativeVolume=4.5m;store.Save("기본",s);store.Save("보수형",s);Check(store.History().Count==3,"SQLite full before/after history");Check(store.Presets().Count==2,"save as preset");store.InsertEvents([Trade(1),Quote(2)]);Check(store.InsertEvents([Trade(1)])==0,"event persistence idempotence");}
        using(var store=new TradingStore(db)){Check(store.Load("기본").Scalping.RelativeVolume==4.5m,"settings survive process-style reopen");var events=store.ReadEvents(Us.Key,"TEST",Epoch,Epoch.AddSeconds(10));Check(events.Count==2&&events[1].TradeSize==null,"nullable quote not treated as trade volume");var csv=Path.Combine(Dir,"data.csv");MarketCsv.Export(csv,events);Check(Serialization.Pack(MarketCsv.Import(csv))==Serialization.Pack(events),"CSV lossless roundtrip");File.AppendAllText(csv,"invalid\n");Throws<InvalidOperationException>(()=>MarketCsv.Import(csv),"bad CSV fails before import transaction");}
        s=Settings();var quality=new DataQualityGate(s.Data,s.Execution);Check(quality.Accept(Trade(1,2,10,100),false,out _),"first cumulative value does not fabricate history");Check(!quality.Accept(Trade(1,2,10,100),false,out _)&&quality.Duplicates==1,"duplicate trade removed");Check(!quality.Accept(Trade(0,2,10,90),false,out _),"out-of-order trade rejected");Check(quality.Accept(Trade(2,2,10,150),false,out _)&&quality.Gaps==1,"cumulative gap detected without manufacturing ticks");Check(!quality.Accept(Quote(1),false,out _),"cross-kind reverse time rejected");Check(!quality.Accept(Trade(3) with {ReceivedTime=Epoch.AddMinutes(10)},true,out _)&&quality.Stale==1,"stale live event rejected");
        long seq=0;var json="{\"trnm\":\"REAL\",\"data\":[{\"type\":\"0B\",\"item\":\"005930\",\"values\":{\"20\":\"093000\",\"10\":\"-70000\",\"11\":\"-100\",\"15\":\"-3\",\"13\":\"1000\"}}]}";
        var parsed=KiwoomTickParser.Parse(json,DateTimeOffset.Parse("2026-09-25T00:30:00Z"),ref seq).Single();Check(parsed.TradePrice==70000&&parsed.TradeSize==3&&parsed.CumulativeVolume==1000&&parsed.PreviousClose==70100,"KR signed price and individual/cumulative volume mapping");
        json="{\"trnm\":\"REAL\",\"data\":[{\"type\":\"FT\",\"item\":\"AAPL\",\"stexTp\":\"ND\",\"values\":{\"21\":\"223000\",\"41\":\"2.01\",\"51\":\"1.99\",\"61\":\"10\",\"71\":\"20\",\"42\":\"2.02\",\"52\":\"1.98\",\"62\":\"30\",\"72\":\"40\"}}]}";
        parsed=KiwoomTickParser.Parse(json,Epoch,ref seq).Single();Check(parsed.Instrument==Us&&parsed.TradeSize==null&&parsed.Bids!.Count==2&&parsed.Asks!.Count==2,"US L2 quote maps actual supplied depth");
        Check(KiwoomMarketDataProvider.Registration([Us],true).Contains("jmcode")&&KiwoomMarketDataProvider.Registration([Us],true,true).Contains("REMOVE"),"US subscription/unsubscription schema");
        var ctx=new MarketContext(Us,s);for(int i=0;i<=100;i++)ctx.Add(Trade(i,2,10));Check(ctx.Rate(10)==ctx.Rate(60)&&ctx.Rate(10)==10,"volume windows normalized to shares/second");
        s.Scalping.Enabled=true;ctx=new(Us,s);ctx.Add(Trade(1));ctx.Add(Quote(2));Check(new ScalpingStrategy().Evaluate(ctx).Buy==null,"scalp warmup prevents trades");
        var repeated=Enumerable.Range(0,10).Select(i=>Trade(i,2)).ToArray();Check(SupportResistanceService.Touches(repeated,2,.1m,1)==1,"consecutive ticks count as one touch");
        var separated=new[]{Trade(0,2),Trade(1,2.2m),Trade(5,2),Trade(6,2.2m),Trade(10,2)};Check(SupportResistanceService.Touches(separated,2,.1m,3)==3,"reentry and time gap produce independent touches");
        s=Settings();s.Analysis.PivotRadius=2;s.Analysis.MinimumTouches=1;ctx=new(Us,s);foreach(var e in new[]{Trade(0,2),Trade(1,3),Trade(2,4)})ctx.Add(e);Check(SupportResistanceService.Levels(ctx).Count==0,"unconfirmed future pivot not exposed");ctx.Add(Trade(3,3));ctx.Add(Trade(4,2));Check(SupportResistanceService.Levels(ctx).Contains(4),"pivot appears after right neighbours arrive");
        Check(VolumeProfileService.Calculate(ctx).Sum(v=>v.Volume)<=ctx.Trades.Sum(t=>t.TradeSize??0),"profile uses individual trades only");
        s=Settings();s.Rebound.Enabled=true;s.Rebound.Use1=true;s.Rebound.Use2=s.Rebound.Use3=s.Rebound.UseHigh=false;s.Rebound.Seconds1=2;s.Rebound.Drop1=10;s.Rebound.ConfirmTicks=2;s.Rebound.BouncePercent=2;
        ctx=new(Us,s);var rebound=new ReboundStrategy();ctx.Add(Trade(0,10));rebound.Evaluate(ctx);ctx.Add(Trade(1,9));rebound.Evaluate(ctx);ctx.Add(Trade(2,8));Check(rebound.Evaluate(ctx).Buy==null,"drop candidate never buys immediately");ctx.Add(Trade(3,8.1m));Check(rebound.Evaluate(ctx).Buy==null,"bounce needs configured confirmation");ctx.Add(Trade(4,8.3m));Check(rebound.Evaluate(ctx).Buy==true,"confirmed bounce emits buy");
        s=Settings();s.Filters.First(f=>f.Name=="시가총액").Enabled=true;ctx=new(Us,s);ctx.Add(Trade(0));Check(new CommonScanner(s).Reject(ctx)!.Contains("데이터 없음"),"required missing fundamental filter blocks entry");s.Filters.ForEach(f=>f.Enabled=false);s.Data.ExcludedSymbols=Us.Key;Check(new CommonScanner(s).Reject(ctx)=="수동 악재 제외","manual bad-news exclusion");
