    private static void PaperAndRiskTests()
    {
        var s=Settings();var paper=new PaperBroker("USD",1000,s.Execution);var o=new ManagedOrder{Id="1",Instrument=Us,Buy=true,Quantity=10,Price=2.02m,Kind=OrderKind.Limit,Created=Epoch};paper.Submit(o);paper.Process(Quote(0));Check(o.Filled==0,"no same-event lookahead fill");paper.Process(Quote(1,size:4));Check(o.Filled==2&&o.State==OrderState.PartiallyFilled,"liquidity participation creates partial fill");Check(paper.Cash==1000-2*2.01m*(1+.001m),"cash includes buy fee");Check(paper.ReservedCash>0,"pending remainder reserves cash");paper.RequestCancel(o,Epoch.AddSeconds(2));Check(o.State==OrderState.CancelRequested,"cancel receipt not completion");paper.Process(Quote(3));Check(o.State==OrderState.Cancelled&&o.Filled==2&&paper.ReservedCash==0,"confirmed cancel releases reservation without extra fill");
        var sell=new ManagedOrder{Id="2",Instrument=Us,Buy=false,Quantity=2,Price=1.99m,Kind=OrderKind.Limit,Created=Epoch.AddSeconds(4)};paper.Submit(sell);paper.Process(Quote(5));Check(sell.State==OrderState.Filled&&paper.Positions[Us.Key].Quantity==0,"sell updates position");Check(paper.Cash-1000==paper.Fills.Where(f=>!f.Buy).Sum(f=>f.RealizedPnl),"round-trip realized PnL includes both side fees");
        paper=new("USD",1000,s.Execution);o=new(){Id="3",Instrument=Us,Buy=true,Quantity=2,Price=1.99m,Created=Epoch,Kind=OrderKind.Limit};paper.Submit(o);paper.Process(Quote(1));Check(o.Filled==0,"passive bid order not instantly filled at ask");paper.Process(Quote(25));Check(o.State==OrderState.CancelRequested,"TTL requests cancel");paper.Process(Quote(26));Check(o.State==OrderState.Cancelled,"TTL cancellation confirms on next event");
        s.Execution.AllowPartial=false;paper=new("USD",1000,s.Execution);o=new(){Instrument=Us,Buy=true,Quantity=100,Price=2.02m,Created=Epoch,Kind=OrderKind.Limit};paper.Submit(o);paper.Process(Quote(1,size:2));Check(o.Filled==0,"partial-disabled model needs sufficient volume");o.State=OrderState.Unknown;paper.Process(Quote(2,size:1000));Check(o.Filled==0,"unknown orders never retried or filled locally");
        s=Settings();var engine=new TradingEngine(s,"USD",1000);engine.OnEvent(Trade(0),false);engine.OnEvent(Quote(1),false);var placed=engine.Manual(Us,true,10,2.02m,OrderKind.Limit);Check(placed!=null,"manual goes through common risk");Check(engine.Manual(Us,true,10,2.02m,OrderKind.Limit)==null,"pending strategy conflict blocks duplicate");engine.EmergencyStop();Check(engine.Risk.Stopped&&placed!.State==OrderState.CancelRequested,"emergency blocks new and cancels pending");Check(engine.Manual(Us,true,1,2.02m,OrderKind.Limit)==null,"manual cannot bypass emergency stop");
        s=Settings();var risk=new RiskManager(s);var ctx=new MarketContext(Us,s);ctx.Add(Trade(0,10));foreach(var mode in Enum.GetValues<SizingMode>()){s.Risk.Sizing=mode;Check(risk.Size(ctx,10000,10)>0,"position sizing "+mode);}
        s.Risk.StopMode=DistanceMode.Atr;Check(risk.Distance(ctx,10,DistanceMode.Atr,2)==0,"ATR warmup is not fabricated");s.Risk.StopMode=DistanceMode.Percent;
        paper=new("USD",1000,s.Execution);o=new(){Instrument=Us,Buy=true,Quantity=10,Price=10,Created=Epoch};Check(risk.Check(o,paper,ctx,1000,s.Risk.MaxDailyTrades)!=null,"daily trade cap");Check(risk.Check(o,paper,ctx,2000,0)!=null,"daily drawdown cap");Check(risk.Check(withQuantity(100000),paper,ctx,1000,0)!=null,"oversized order rejected");
        var foreign=new ManagedOrder{Instrument=new("005930",Exchange.KRX),Buy=false,Quantity=1,Price=70000};Check(risk.Check(foreign,paper,ctx,1000,0)=="다른 통화 주문 금지","KRW/USD never mixed even for sells");
        ManagedOrder withQuantity(int q)=>new(){Instrument=Us,Buy=true,Quantity=q,Price=10,Created=Epoch};
    }
    private static void BacktestTests()
    {
        using var store=new TradingStore(Path.Combine(Dir,"backtest.db"));var settings=new TradingSettings();var data=DemoMarketDataProvider.Sample(Us);Check(data.Take(100).Where(e=>e.Kind==EventKind.Trade).All(e=>e.High<=data.Take(100).Where(x=>x.Kind==EventKind.Trade&&x.ExchangeTime<=e.ExchangeTime).Max(x=>x.TradePrice)),"sample OHLC contains no later high");
        var runner=new BacktestRunner(store);var a=runner.Run(settings,data,CancellationToken.None);var b=runner.Run(settings,data,CancellationToken.None);Check(a.Events==data.Count&&a.Fills>0,"backtest executes actual strategy trades");Check(a.DataHash==b.DataHash&&a.NetPnl==b.NetPnl&&Serialization.Pack(a.Trades)==Serialization.Pack(b.Trades),"deterministic replay and accounting");Check(a.Fees>0&&a.Equity.Count>0&&a.MaxDrawdownPercent>=0,"fees equity drawdown results");Check(store.RecentAudit().Count>0,"decisions/orders/fills persisted");using var cancel=new CancellationTokenSource();cancel.Cancel();Check(runner.Run(settings,data,cancel.Token).Status=="취소","backtest cancellation returns recorded partial result");Throws<InvalidOperationException>(()=>runner.Run(settings,[Trade(1) with {Instrument=new("005930",Exchange.KRX)}],CancellationToken.None),"backtest mixed market rejected");
    }
